// @ts-nocheck
import { rest } from 'msw'

import type { RegisterAPIBody, RegisterAPIResponse } from 'src/hooks/api/authHooks'

interface RegisterRequestParams {}

interface LoginRequestBody {
  email: string
  password: string
}
interface LoginRequestParams {}
interface LoginResponseBody {
  accessToken: string
  expiresIn: string
  refreshToken: string
  refreshTokenExpiresIn: string
  user: {
    id: number
    name: string
    studentId: string
    phoneNumber: string
    email: string
    department: string
    nickname: string
  }
}

interface LogoutRequestBody {}
interface LogoutRequestParams {}
interface LogoutResponseBody {}

interface ResetPasswordRequestBody {
  newPassword: string
}
interface ResetPasswordRequestParams {}
interface ResetPasswordResponseBody {}

export const AuthHandlers = [
  rest.post<LoginRequestBody, LoginRequestParams, LoginResponseBody>('/auth/login', async (req, res, ctx) => {
    const { email, password } = await req.json()
    if (email === null || password === null) {
      return res(ctx.status(400), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }
    if (email === 'notexist@example.com') {
      return res(
        ctx.status(401, 'user does not exist'),
        ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000')
      )
    }
    if (password === 'notmatch') {
      return res(
        ctx.status(400, 'password does not match'),
        ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000')
      )
    }

    const user = {
      id: 1,
      name: '김승현',
      studentId: '2019320048',
      phoneNumber: '010-8415-9533',
      email: 'shkim9533@korea.ac.kr',
      department: '정보대학 컴퓨터학과',
      nickname: '별 헤는 밤',
      clubs: [
        {
          id: 1,
          name: 'KWEB',
          permission: 'SUPERADMIN',
          isConnected: true,
          semester: 'SPRING',
          year: 2023,
          searchable: true
        },
        {
          id: 2,
          name: 'KUICS',
          permission: 'ADMIN',
          isConnected: false,
          semester: 'FALL',
          year: 2022,
          searchable: false
        },
        {
          id: 3,
          name: '그루터기',
          permission: 'USER',
          isConnected: false,
          semester: 'SPRING',
          year: 2023,
          searchable: true
        },
        {
          id: 4,
          name: 'AIKU',
          permission: 'USER',
          isConnected: true,
          semester: 'SPRING',
          year: 2023,
          searchable: true
        }
      ],
      likes: [
        {
          clubId: 1,
          name: 'KWEB'
        },
        {
          clubId: 2,
          name: 'KUICS'
        }
      ]
    }
    return res(
      ctx.status(200),
      ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'),
      ctx.json({
        accessToken: 'ACCESS_TOKEN',
        expiresIn: '86400',
        refreshToken: 'REFRESH_TOKEN',
        refreshTokenExpiresIn: '604800',
        user
      })
    )
  }),
  rest.post<RegisterAPIBody, RegisterRequestParams, RegisterAPIResponse>('/auth/register', async (req, res, ctx) => {
    const body = await req.json()
    if (Object.keys(body).filter(key => body[key] === null).length > 0) {
      return res(ctx.status(400), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }

    const { email, studentId, ...userData } = body
    if (email === 'duplicate@example.com') {
      return res(
        ctx.status(400, `email : '${email}' already exists`),
        ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000')
      )
    }
    if (studentId === '0000000000') {
      return res(
        ctx.status(400, `'${studentId}' already exists`),
        ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000')
      )
    }

    return res(
      ctx.status(200),
      ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'),
      ctx.json({ id: 2, email, studentId, ...userData })
    )
  }),
  rest.post<LogoutRequestBody, LogoutRequestParams, LogoutResponseBody>('/auth/logout', (req, res, ctx) => {
    const accessToken = req.headers.get('Authorization')
    if (accessToken !== 'Bearer ACCESS_TOKEN') {
      return res(ctx.status(401, 'invalid user!'), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }
    return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
  }),
  rest.put('/auth/refreshAccessToken', (req, res, ctx) => {
    const refreshToken = req.headers.get('refreshToken')

    if (!refreshToken)
      return res(ctx.status(401, 'invalid user!'), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))

    return res(
      ctx.status(200),
      ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'),
      ctx.json({
        accessToken: 'ACCESS_TOKEN',
        expiresIn: '86400',
        refreshToken: 'REFRESH_TOKEN',
        refreshTokenExpiresIn: '604800'
      })
    )
  }),
  rest.put<ResetPasswordRequestBody, ResetPasswordRequestParams, ResetPasswordResponseBody>(
    `/auth/password/reset`,
    async (req, res, ctx) => {
      const { newPassword } = await req.json()

      if (newPassword === null) {
        return res(ctx.status(400), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
      }

      return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }
  ),
  rest.get('/auth/confirm/:id', (req, res, ctx) => {
    return res(ctx.status(200))
  })
]
