import { AxiosError } from 'axios'
import { useSnackbar } from 'notistack'
import { useState } from 'react'
import { useAuthHeader, useAuthUser } from 'react-auth-kit'
import { Helmet } from 'react-helmet-async'
import { Navigate, useNavigate, useParams } from 'react-router'

import {
  Box,
  Button,
  Checkbox,
  FormControl,
  FormControlLabel,
  InputLabel,
  ListSubheader,
  MenuItem,
  Paper,
  Select,
  type SelectChangeEvent,
  TextField,
  type TextFieldProps,
  Typography,
  useMediaQuery
} from '@mui/material'
import { styled, useTheme } from '@mui/material/styles'

import DEPARTMENTS from 'src/data/departments'
import { AUTH_USER_MESSAGE, HELPER_TEXT_MESSAGE, USER_AGREEMENT_MESSAGE } from 'src/data/messages'

import { formatLikePhoneNumber } from 'src/utils/formatLikePhoneNumber '
import { isCollegeType } from 'src/utils/typeChecker'

import type { ClubMemberForAuth } from 'src/models/clubMember'

import { putUserInformation, usePatchUserAgreement } from 'src/hooks/api/member'
import useSafeAuthUser from 'src/hooks/useSafeAuthUser'
import useUpdateAuthState from 'src/hooks/useUpdateAuthUser'

const INPUT_NAMES = {
  NAME: 'name',
  PHONE_NUMBER: 'phoneNumber',
  DEPARTMENT: 'department'
} as const

const validateNameText = (name: string) => {
  const trimmedName = name.trim()
  if (trimmedName !== name) {
    throw new Error('이름 앞뒤에 공백문자를 포함할 수 없습니다.')
  }

  const regex = /^[a-zA-Z0-9ㄱ-ㅎㅏ-ㅣ가-힣 ]*$/
  const isValid = regex.test(name)
  if (!isValid) {
    throw new Error('이름에 특수문자를 포함할 수 없습니다.')
  }
}

const AgreementPageProps: React.FC = () => {
  const { id } = useParams()
  const clubId = Number(id)

  const navigate = useNavigate()
  const authHeader = useAuthHeader()
  const authUser = useAuthUser()

  const { spacing, breakpoints, colors } = useTheme()
  const isUpperThanSm = useMediaQuery(breakpoints.up('sm'))

  const updateAuthState = useUpdateAuthState()
  const { enqueueSnackbar } = useSnackbar()

  const [isChecked, setIsChecked] = useState(false)

  const { userInfo, isLoggedIn } = useSafeAuthUser()

  const [inputValues, setInputValues] = useState({
    [INPUT_NAMES.NAME]: userInfo?.name ?? '',
    [INPUT_NAMES.PHONE_NUMBER]: userInfo?.phoneNumber ?? '',
    [INPUT_NAMES.DEPARTMENT]: userInfo?.department ?? DEPARTMENTS['간호대학'][0]
  })
  const patchUserAgreementMutation = usePatchUserAgreement(clubId)
  // const putUserInformationMutation = usePutUserInformation({ ...inputValues, nickname: userInfo?.nickname ?? '' })

  const userClub = userInfo?.clubs.find(c => c.id === clubId)
  const isConnected = !!userClub && userClub?.isConnected

  const handleInputChange = ({
    target
  }: SelectChangeEvent | React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { value, name } = target

    setInputValues(prev => ({
      ...prev,
      [name]: value
    }))

    if (name !== INPUT_NAMES.NAME || !(target instanceof HTMLInputElement)) return

    try {
      validateNameText(value)
      target.setCustomValidity('')
    } catch (err) {
      if (err instanceof Error) target.setCustomValidity(err.message)
    }
  }

  const handlePhoneNumberChange: React.ChangeEventHandler<HTMLTextAreaElement> = ({ target: { value } }) => {
    setInputValues(prevState => ({ ...prevState, phoneNumber: formatLikePhoneNumber(value) }))
  }

  const handleFormSubmit: React.FormEventHandler<HTMLFormElement> = async e => {
    e.preventDefault()

    const { name, phoneNumber, department } = inputValues
    if (!isChecked || !name || !phoneNumber || !department) return

    try {
      // putUserInformationMutation.mutate()
      await putUserInformation({ user: { ...inputValues, nickname: userInfo?.nickname ?? '' }, token: authHeader() })

      await patchUserAgreementMutation.mutateAsync()

      const unsafeUser = authUser()
      if (!unsafeUser) {
        throw Error
      }
      const clubs = unsafeUser.clubs.map((club: ClubMemberForAuth) => {
        return {
          ...club,
          isConnected: club.id === clubId ? true : club.isConnected
        }
      })

      updateAuthState(unsafeUser, clubs, [...unsafeUser.likes])
      enqueueSnackbar(USER_AGREEMENT_MESSAGE.SUCCESS, { variant: 'success' })
      return <Navigate to=".." />
    } catch (err) {
      if (err instanceof AxiosError) {
        enqueueSnackbar(err.response?.data?.message ?? USER_AGREEMENT_MESSAGE.SERVER_ERROR, {
          variant: 'error'
        })
        return
      }
      enqueueSnackbar(USER_AGREEMENT_MESSAGE.UNKNOWN_ERROR, {
        variant: 'error'
      })
    }
  }

  const handleCancelButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate(-1)
  }

  const handleCheckboxChange: React.ChangeEventHandler<HTMLInputElement> = () => {
    setIsChecked(prev => !prev)
  }

  if (!userInfo && isLoggedIn) {
    enqueueSnackbar(AUTH_USER_MESSAGE.WRONG_AUTH_STATE, { variant: 'error' })
    return <Navigate to="/" />
  }

  return (
    <PageWrapper>
      <Helmet>
        <title>동아리 지원</title>
      </Helmet>
      <Paper
        square={!isUpperThanSm}
        sx={{
          my: spacing(8),
          padding: 3,
          flex: 1,
          maxWidth: '480px',
          [breakpoints.down('sm')]: {
            my: 0,
            py: 5,
            maxWidth: '100%'
          }
        }}
      >
        <Typography component="h1" variant="h3" sx={{ mb: 2, textAlign: 'center' }}>
          내 정보 제출하기
        </Typography>
        {isConnected ? (
          <>
            <Typography color={colors.primary.main} variant="body1" sx={{ mb: 2, textAlign: 'center' }}>
              이미 제출이 완료되었습니다.
            </Typography>
            <Button type="button" variant="outlined" fullWidth sx={{ mt: 1 }} onClick={handleCancelButtonClick}>
              돌아가기
            </Button>
          </>
        ) : (
          <Box
            component="form"
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              '& .MuiTextField-root': { margin: 1 }
            }}
            onSubmit={handleFormSubmit}
          >
            <CustomTextField
              id="email"
              type="email"
              label="이메일"
              defaultValue={userInfo?.email}
              inputProps={{ readOnly: true }}
              disabled
            />
            <CustomTextField
              id="student-id"
              type="text"
              label="학번"
              defaultValue={userInfo?.studentId}
              inputProps={{ readOnly: true, maxLength: 15 }}
              disabled
            />
            <CustomTextField
              id={INPUT_NAMES.NAME}
              name={INPUT_NAMES.NAME}
              type="text"
              label="이름"
              placeholder="홍길동"
              defaultValue={userInfo?.name}
              inputProps={{ maxLength: 50 }}
              onChange={handleInputChange}
            />
            <CustomTextField
              id={INPUT_NAMES.PHONE_NUMBER}
              name={INPUT_NAMES.PHONE_NUMBER}
              type="tel"
              label="전화번호"
              placeholder="010-0000-0000"
              defaultValue={userInfo?.phoneNumber}
              value={inputValues.phoneNumber}
              helperText={HELPER_TEXT_MESSAGE.PHONE_NUMBER}
              inputProps={{ pattern: '010-[0-9]{4}-[0-9]{4}', maxLength: 13 }}
              onChange={handlePhoneNumberChange}
            />
            <FormControl sx={{ margin: 1, width: '100%' }} size="small" required>
              <InputLabel htmlFor={INPUT_NAMES.DEPARTMENT}>학과/학부</InputLabel>
              <Select
                id={INPUT_NAMES.DEPARTMENT}
                name={INPUT_NAMES.DEPARTMENT}
                label="학과/학부"
                defaultValue={userInfo?.department}
                onChange={handleInputChange}
                placeholder="학과/학부"
                fullWidth
              >
                {Object.keys(DEPARTMENTS).map(college => {
                  if (!isCollegeType(college)) return
                  // 직계 children으로 설정하지 않으면 mui select의 option 요소로 인식하지 않음 - Fragment로 감싸도 인식하지 못함
                  return [
                    <ListSubheader key={college} sx={{ fontWeight: 'bold' }}>
                      {college}
                    </ListSubheader>,
                    DEPARTMENTS[college].map(department => (
                      <MenuItem
                        key={department}
                        value={college === department ? department : `${college} ${department}`}
                      >
                        {department}
                      </MenuItem>
                    ))
                  ]
                })}
              </Select>
            </FormControl>
            <Box
              sx={{
                margin: spacing(1.5, 0, 0),
                padding: spacing(1.5, 1.5, 2),
                borderRadius: '0.75rem',
                backgroundColor: colors.secondary.lighter
              }}
            >
              <Typography component="h2" variant="h6" align="center" sx={{ mb: spacing(1), fontSize: '1rem' }}>
                제출 시 유의사항
              </Typography>
              <Typography component="p" variant="body2">
                회원님의 소중한 개인정보를 보호하기 위해 현재 해당 동아리 운영진에게&nbsp;
                <strong>회원님의 정보를 제공하고 있지 않습니다.</strong>
                <br />
                그러나 위 정보를 제출하신다면, 동아리 회원 명단에 연동되어 운영진에게&nbsp;
                <strong>더 정확한 연락처를 제공하실 수 있습니다.</strong>&nbsp;이를 통해 각종 누락을 피할 수 있습니다.
              </Typography>
            </Box>
            <FormControlLabel
              control={<Checkbox required checked={isChecked} onChange={handleCheckboxChange} />}
              label="상기 내용을 확인하였으며, 정보 제출에 동의합니다."
              sx={{ mb: spacing(1) }}
            />
            <ButtonsContainer>
              <Button type="button" fullWidth sx={{ mt: 1 }} onClick={handleCancelButtonClick}>
                취소
              </Button>
              <Button type="submit" variant="contained" fullWidth sx={{ mt: 1 }}>
                제출
              </Button>
            </ButtonsContainer>
          </Box>
        )}
      </Paper>
    </PageWrapper>
  )
}

export default AgreementPageProps

const PageWrapper: React.FC = styled(Box)(
  () => `
        display: flex;
        justify-content: center;
        align-items: center;
    `
)

type CustomTextFieldProps = Pick<
  TextFieldProps,
  | 'id'
  | 'label'
  | 'type'
  | 'defaultValue'
  | 'inputProps'
  | 'onChange'
  | 'name'
  | 'placeholder'
  | 'helperText'
  | 'disabled'
  | 'value'
>

const CustomTextField: React.FC<CustomTextFieldProps> = ({ ...props }) => (
  <TextField size="small" {...props} fullWidth required />
)

const ButtonsContainer: React.FC = styled(Box)(
  ({ theme: { spacing } }) => `
  width: 100%;

  display: flex;
  justify-content: space-between;
  column-gap: ${spacing(2)};
  margin: ${spacing(1.5, 0, 0)};
  padding: ${spacing(0)};
  `
)
