import { useSnackbar } from 'notistack'
import { useSignIn, useSignOut } from 'react-auth-kit'

import { AUTH_AUTO_LOGIN_MESSAGE } from 'src/data/messages'

import type { User } from 'src/models/user'

import type { AuthStateUserObject } from 'react-auth-kit/dist/types'

const useUpdateAuthState = () => {
  const signIn = useSignIn()
  const signOut = useSignOut()
  const { enqueueSnackbar } = useSnackbar()
  const accessToken = localStorage.getItem('_auth')
  const refreshToken = localStorage.getItem('_auth_refresh')
  const expiresIn = localStorage.getItem('_auth_storage')
  const refreshTokenExpireIn = localStorage.getItem('_auth_refresh_time')

  return (user: AuthStateUserObject, clubs: User['clubs'], likes: User['likes']) => {
    if (!(accessToken && refreshToken && expiresIn && refreshTokenExpireIn)) {
      signOut()
      enqueueSnackbar(AUTH_AUTO_LOGIN_MESSAGE.FAIL, { variant: 'error' })
      return
    }

    const now = new Date()
    const updatedExpiresIn = Math.floor((new Date(expiresIn).getTime() - now.getTime()) / (60 * 1000))
    const updatedRefreshTokenExpiresIn = Math.floor(
      (new Date(refreshTokenExpireIn).getTime() - now.getTime()) / (60 * 1000)
    )
    try {
      signIn({
        token: accessToken,
        expiresIn: updatedExpiresIn,
        tokenType: 'Bearer',
        authState: { ...user, clubs, likes },
        refreshToken: refreshToken,
        refreshTokenExpireIn: updatedRefreshTokenExpiresIn
      })
    } catch (error) {
      enqueueSnackbar(AUTH_AUTO_LOGIN_MESSAGE.FAIL, { variant: 'warning' })
    }
  }
}

export default useUpdateAuthState
