import React, { useEffect, useState } from 'react'
import { Outlet, useLocation } from 'react-router-dom'

import { Box, alpha, lighten, styled, useMediaQuery, useTheme } from '@mui/material'

import Footer from 'src/components/Footer'
import Header from 'src/components/Header'
import Sidebar from 'src/components/Sidebar'

const ThemeWrapper = styled(Box)(
  () => `
      position: relative;
      z-index: 5;
      display: block;
      flex: 1;
      min-width: 0;
  `
)

export interface SidebarProps {
  open: boolean
  handleDrawerClick?: React.MouseEventHandler<HTMLButtonElement>
}

const SidebarLayout = () => {
  const theme = useTheme()
  const isPc = useMediaQuery(theme.breakpoints.up('lg'))
  const isNotRegisterPage = window.location.pathname != '/club/register'
  const location = useLocation()
  const [open, setOpen] = useState(isPc)

  useEffect(() => {
    setOpen(isPc && isNotRegisterPage)
  }, [isPc, isNotRegisterPage])

  const handleDrawerClick: React.MouseEventHandler<HTMLButtonElement> = () => handleOpen()
  const handleOpen = () => setOpen(!open)
  return (
    <Box
      width="100%"
      minHeight="100%"
      sx={{
        display: 'flex',
        flexDirection: 'row',
        '.MuiPageTitle-wrapper': {
          background: theme.palette.mode === 'dark' ? theme.colors.alpha.trueWhite[5] : theme.colors.alpha.white[50],
          marginBottom: `${theme.spacing(4)}`,
          boxShadow:
            theme.palette.mode === 'dark'
              ? `0 1px 0 ${alpha(
                  lighten(theme.colors.primary.main, 0.7),
                  0.15
                )}, 0px 2px 4px -3px rgba(0, 0, 0, 0.2), 0px 5px 12px -4px rgba(0, 0, 0, .1)`
              : `0px 2px 4px -3px ${alpha(theme.colors.alpha.black[100], 0.1)}, 0px 5px 12px -4px ${alpha(
                  theme.colors.alpha.black[100],
                  0.05
                )}`
        }
      }}
    >
      <Sidebar open={open} handleDrawerClick={handleDrawerClick} />
      <Box minWidth="0" sx={{ flex: 1 }}>
        <Header open={open} handleDrawerClick={handleDrawerClick} />
        <ThemeWrapper>
          <Outlet />
        </ThemeWrapper>
        {(isPc || !location?.pathname.startsWith('/auth')) && <Footer />}
      </Box>
    </Box>
  )
}

export default SidebarLayout
