import { Box, Button, TextField as MuiTextField, type TextFieldProps } from '@mui/material'

interface UpdatePasswordFormProps {
  isForgotPassword: boolean
  handleChange: React.ChangeEventHandler<HTMLTextAreaElement | HTMLInputElement>
  onClickSubmit: React.FormEventHandler<HTMLFormElement>
  onClickCancel: React.MouseEventHandler<HTMLButtonElement>
}

const TextField = (props: TextFieldProps) => <MuiTextField size="small" required fullWidth {...props} />

function NewPasswordForm({ isForgotPassword, handleChange, onClickSubmit, onClickCancel }: UpdatePasswordFormProps) {
  return (
    <Box
      component="form"
      sx={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        '& .MuiTextField-root': { margin: 1 }
      }}
      onSubmit={onClickSubmit}
    >
      {!isForgotPassword && (
        <TextField
          id="current-password"
          name="currentPassword"
          type="password"
          label="현재 비밀번호"
          onChange={handleChange}
        />
      )}
      <TextField id="new-password" name="newPassword" type="password" label="새 비밀번호" onChange={handleChange} />
      <TextField id="confirm-password" type="password" label="비밀번호 확인" onChange={handleChange} />
      <Button type="submit" variant="contained" fullWidth sx={{ mt: 1 }}>
        비밀번호 수정
      </Button>
      <Button variant="outlined" fullWidth onClick={onClickCancel} sx={{ mt: 1 }}>
        취소
      </Button>
    </Box>
  )
}

export default NewPasswordForm
