import { rest } from 'msw'

import CLUB_REVIEWS from 'src/mocks/data/reviews'

export const ReviewHandlers = [
  rest.post('/club/:clubId/review', (req, res, ctx) => {
    return res(
      ctx.status(200),
      ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'),
      ctx.json({ message: 'ok' })
    )
  }),
  rest.get('/club/:clubId/review', (req, res, ctx) => {
    return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'), ctx.json(CLUB_REVIEWS))
  }),
  rest.get('/user/reviews', (req, res, ctx) => {
    return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'), ctx.json(CLUB_REVIEWS))
  }),
  rest.delete('/club/:clubId/review/:reviewId', (req, res, ctx) => {
    return res(
      ctx.status(200),
      ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'),
      ctx.json({ message: 'ok' })
    )
  })
]
